#!/usr/bin/env python3
import argparse
import json
import re
import urllib.request
import sys
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path

# --- Configuration (Inlined) ---

@dataclass(frozen=True)
class Weights:
    analytics: float = 0.40
    situational: float = 0.20
    injury: float = 0.20
    motivation: float = 0.10
    market: float = 0.10

@dataclass(frozen=True)
class PointValues:
    home_field_base: float = 3.0
    motivation_boost: float = 2.0

# --- Data Fetching Logic (from fetch_games.py) ---

SB_URL = "https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard?seasontype=2&week={week}"
DIVISIONS = {
    "AFC East": "BUF MIA NE NYJ", "AFC North": "BAL CIN CLE PIT",
    "AFC South": "HOU IND JAX TEN", "AFC West": "DEN KC LV LAC",
    "NFC East": "DAL NYG PHI WSH", "NFC North": "CHI DET GB MIN",
    "NFC South": "ATL CAR NO TB", "NFC West": "ARI LAR SF SEA",
}
_TEAM_DIV = {t: d for d, ts in DIVISIONS.items() for t in ts.split()}
_FAV_RE = re.compile(r"\s*([A-Z]{2,3})\s*(-?\d+(?:\.\d+)?)\s*")

def fetch_scoreboard(week: int) -> dict:
    req = urllib.request.Request(SB_URL.format(week=week), headers={"User-Agent": "curl/8.5.0"})
    with urllib.request.urlopen(req, timeout=25) as r:
        return json.load(r)

def parse_game(event: dict) -> dict:
    comp = event["competitions"][0]
    away_abbr = home_abbr = None
    for c in comp["competitors"]:
        abbr = c["team"]["abbreviation"]
        if c.get("homeAway") == "home": home_abbr = abbr
        else: away_abbr = abbr

    favorite, spread = home_abbr, None
    odds = comp.get("odds") or []
    if odds:
        o = odds[0]
        m = _FAV_RE.match(o.get("details") or "")
        if m:
            favorite = m.group(1)
            spread = abs(float(m.group(2)))
        else:
            for side in ("homeTeamOdds", "awayTeamOdds"):
                s = o.get(side) or {}
                if s.get("favorite"):
                    favorite = s["team"]["abbreviation"]
                    break

    return {
        "away": away_abbr, "home": home_abbr, "favorite": favorite,
        "spread": spread, "divisional": _TEAM_DIV.get(away_abbr) == _TEAM_DIV.get(home_abbr) and _TEAM_DIV.get(away_abbr) is not None,
        "injury_delta": 0.0, "ratings": {away_abbr: None, home_abbr: None}
    }

# --- Scoring & Confidence Logic ---

def map_confidence_to_scale(conf_float: float) -> int:
    if conf_float >= 85: return 5
    if conf_float >= 75: return 4
    if conf_float >= 65: return 3
    if conf_float >= 55: return 2
    return 1

def score_game(g: dict, w: Weights, p: PointValues) -> dict:
    fav_is_home = g["favorite"] == g["home"]
    fav_rating = g["ratings"].get(g["favorite"], 0.0)
    dog_key = g["away"] if fav_is_home else g["home"]
    dog_rating = g["ratings"].get(dog_key, 0.0)
    spread = g.get("spread") or 0.0

    analytics = fav_rating - dog_rating
    home_hfa = p.home_field_base if fav_is_home else 0.0
    injury = g.get("injury_delta", 0.0)
    rivalry = 1.0 if g.get("divisional") else 0.0

    proj = (w.analytics * analytics) + (w.situational * home_hfa) + \
           (w.injury * injury) + (w.motivation * p.motivation_boost * rivalry) + (w.market * spread)

    disagreement = abs(proj - spread)
    conf_float = max(0.0, min(95.0, 45.0 + 4.0 * proj - 2.0 * disagreement))

    dog = g["away"] if fav_is_home else g["home"]
    return {
        "pick": f"{g['favorite']} over {dog}",
        "proj_margin": round(proj, 1),
        "market_spread": spread,
        "confidence_score": map_confidence_to_scale(conf_float)
    }

# --- CLI Implementation ---

def main():
    parser = argparse.ArgumentParser(description="NFL Helper: Schedule and Predictions")
    parser.add_argument("mode", choices=["list", "predict"], help="Mode: 'list' for schedule, 'predict' for picks")
    parser.add_argument("--week", type=int, required=True, help="NFL Week number")
    parser.add_argument("--season", type=int, default=2026, help="NFL Season")
    parser.add_argument("--file", help="Path to existing games.json file (if not using 'list' mode)")
    args = parser.parse_args()

    w, p = Weights(), PointValues()

    if args.mode == "list":
        print(f"--- NFL {args.season} Week {args.week} Schedule ---")
        try:
            data = fetch_scoreboard(args.week)
            for ev in data.get("events", []):
                g = parse_game(ev)
                print(f"{g['away']} @ {g['home']}")
        except Exception as e:
            print(f"Error fetching schedule: {e}")

    elif args.mode == "predict":
        file_path = args.file or f"week{args.week}_{args.season}_games.json"
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)

            picks = []
            for g in data.get("games", []):
                # Ensure ratings exist for scoring (using dummy 0.0 if missing for this v1)
                if "ratings" not in g or not g["ratings"]:
                    g["ratings"] = {team: 0.0 for team in [g["away"], g["home"]]}
                picks.append(score_game(g, w, p))

            picks.sort(key=lambda x: x["confidence_score"], reverse=True)

            print(f"\n--- NFL {args.season} Week {args.week} PICKS ---")
            print(f"{'CONF':<6} | {'PICK':<25} | {'PROJ':<6} | {'MKT':<6}")
            print("-" * 55)
            for pk in picks:
                print(f"{pk['confidence_score']}/5   | {pk['pick']:<25} | {pk['proj_margin']:>5} | {pk['market_spread']:>5}")
        except FileNotFoundError:
            print(f"Error: File {file_path} not found. Use 'list' mode to fetch first.")
        except Exception as e:
            print(f"Error: {e}")

if __name__ == "__main__":
    main()

